const D = { density: .5, scale: 1, energy: .55, speed: 1, hue: 195, wobble: .5, pop: .5, style: 'glass', act: 'rise', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const u = Math.min(width, height);
const sty = P.style;
const N = Math.max(8, Math.min(110, Math.round(14 + P.density * 96)));

if (!S.bb || S.bn !== N || S.bseed !== P.seed) {
  S.bb = [];
  for (let i = 0; i < N; i++) {
    S.bb.push({
      col: fr(i),
      y0: fr(i + 1),
      sp: 0.5 + fr(i + 2) * 1.1,
      rad: 0.35 + fr(i + 3) * 1.0,
      ph: fr(i + 4) * TAU,
      sw: 0.5 + fr(i + 5) * 1.2,
      hu: (fr(i + 6) - 0.5) * 44,
      lane: fr(i + 7)
    });
  }
  S.bn = N; S.bseed = P.seed;
}

const t = K.t;
const inten = 0.5 + 0.5 * K.intensity;
const riseSpd = (0.04 + 0.12 * P.energy) * P.speed * inten;
const breathe = 0.9 + 0.16 * K.swell + A.bass * 0.35;
const sec = ((Math.floor(K.section) % 8) + 8) % 8;

// act: rise = steady stream, cauldron = boil from a vent, ascend = slow serene drift
const ACT = {
  rise:     { spdK: 1, vent: 0, wobK: 1 },
  cauldron: { spdK: 1.5, vent: 0.7, wobK: 1.7 },
  ascend:   { spdK: 0.55, vent: 0, wobK: 0.6 } };
const ac = ACT[P.act] || ACT.rise;

// beat pop: a fraction of bubbles "pop" briefly on the kick (partial-frame, no strobe)
const popPhase = K.pulse * P.pop;

const add = (sty === 'iridescent' || sty === 'thermal');
push();
if (add) blendMode(ADD);

for (let i = 0; i < N; i++) {
  const b = S.bb[i];
  let fy = (b.y0 + riseSpd * b.sp * ac.spdK * t) % 1.15;
  if (fy < 0) fy += 1.15;
  const y = height * (1.08 - fy * 1.16);
  const ventPull = ac.vent * (0.5 - Math.abs(b.lane - 0.5)) * (1 - fy) * u * 0.25;
  const x = b.col * width
    + Math.sin(t * b.sw * 0.9 + b.ph) * u * 0.02 * b.sw * P.wobble * ac.wobK
    + Math.sin(t * 0.3 + b.ph * 2) * u * 0.01
    + ventPull;
  let r = u * 0.03 * P.scale * b.rad * breathe;
  // pop shrink near the top for a fraction of bubbles
  const popped = (fr(i + 900) < popPhase && fy > 0.8);
  if (popped) r *= 0.5 + 0.5 * (1 - popPhase);
  const h = hw(P.hue + b.hu);
  const air = 0.4 + 0.5 * P.energy;

  push();
  translate(x, y);

  if (sty === 'xray') {
    noFill(); stroke(hw(P.hue), 18, 100, 42);
    strokeWeight(1);
    ellipse(0, 0, r * 2, r * 2);
    ellipse(0, 0, r * 1.3, r * 1.3);
    stroke(hw(P.hue), 12, 100, 26);
    line(-r, 0, r, 0); line(0, -r, 0, r);
    point(0, 0); noStroke();
  } else if (sty === 'iridescent') {
    noStroke();
    for (let l = 0; l < 3; l++) {
      const oh = hw(h + l * 40 + Math.sin(t * 1.2 + i + l) * 30);
      fill(oh, 55 - l * 12, 100, 12 * air);
      const off = r * 0.16 * l;
      ellipse(Math.cos(t + i) * off, Math.sin(t + i) * off, r * 2 * (1 - l * 0.12), r * 2 * (1 - l * 0.12));
    }
    fill(hw(h + 60), 20, 100, 24 * air); ellipse(-r * 0.3, -r * 0.32, r * 0.6, r * 0.6);
  } else if (sty === 'ink') {
    noFill(); stroke(hw(P.hue), 10, 24, 60); strokeWeight(u * 0.0016 * (1 + b.rad));
    ellipse(0, 0, r * 2, r * 2);
    noStroke(); fill(hw(P.hue), 6, 16, 12); ellipse(0, 0, r * 1.7, r * 1.7);
    fill(0, 0, 50, 30); ellipse(-r * 0.3, -r * 0.32, r * 0.42, r * 0.42);
  } else if (sty === 'thermal') {
    noStroke();
    const heat = 0.3 + 0.7 * fy;
    fill(hw(255 - heat * 235), 85, 100, 16 * air); ellipse(0, 0, r * 2, r * 2);
    fill(hw(60 - heat * 30), 70, 100, 20 * air); ellipse(0, 0, r * 1.1, r * 1.1);
  } else {
    // glass (default) — refractive translucent sphere + thin-film rim + specular
    noStroke();
    fill(h, 30, 100, 20 * air); ellipse(0, 0, r * 2, r * 2);
    fill(h, 14, 100, 16 * air); ellipse(0, 0, r * 1.5, r * 1.5);
    noFill(); stroke(hw(h + 40), 45, 100, 48 * air); strokeWeight(u * 0.0026);
    ellipse(0, 0, r * 1.94, r * 1.94);
    stroke(hw(h - 30), 32, 100, 28 * air); strokeWeight(u * 0.0016);
    arc(0, 0, r * 1.7, r * 1.7, TAU * 0.55, TAU * 0.85);
    noStroke();
    fill(0, 0, 100, 58 * air); ellipse(-r * 0.34, -r * 0.36, r * 0.5, r * 0.36);
    fill(0, 0, 100, 30 * air); ellipse(r * 0.3, r * 0.28, r * 0.22, r * 0.22);
  }
  pop();
}

if (add) blendMode(BLEND);
pop();
drawingContext.shadowBlur = 0;
